SELECT id, order_id, ROUND(cost / SUM(cost) OVER (PARTITION BY carrier), 4) AS cost_share, SUM(cost) OVER (PARTITION BY carrier ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost, ROUND(cost / SUM(cost) OVER (PARTITION BY carrier), 4) AS cost_share_2, NTILE(5) OVER (ORDER BY cost DESC, id) AS cost_bucket FROM shipments WHERE carrier NOT IN ('DHL', 'UPS', 'Kerry');
